#!/usr/bin/env node
// Generated by herdr-common from pack.config.mjs. Do not edit directly; run sync.
import { existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const common = resolve(process.env.HERDR_COMMON ?? resolve(root, "../herdr-common"));
const syncMod = resolve(common, "src/sync.mjs");
if (!existsSync(syncMod)) {
  throw new Error(`herdr-common not found at ${common}. Place herdr-common next to this repo or set HERDR_COMMON.`);
}
const { syncPack, checkPackSync } = await import(pathToFileURL(syncMod).href);

if (process.argv.includes("--check")) {
  const res = await checkPackSync(root);
  if (!res.ok) {
    console.error(`[FAIL] ${res.pack.name} is out of sync with herdr-common:`, { missing: res.missing, drifted: res.drifted, stale: res.stale });
    process.exit(1);
  }
  console.log(`[ok] ${res.pack.name} is in sync with herdr-common.`);
} else {
  const res = await syncPack(root);
  console.log(`[sync] ${res.pack.name}: ${res.written.length} updated, ${res.unchanged.length} unchanged${res.removed.length ? `, ${res.removed.length} removed` : ""}`);
}
